INSERT INTO message_templates (id,name,category,channel,subject,body,active,created_by) VALUES (1,'Application received','acknowledgement','email','We received your application for {{job_title}}','Hi {{first_name}},

Thanks for applying to {{job_title}} at VSolutions. Our team is reviewing your background and will be in touch within 5 business days.

Best,
VSolutions Talent Team',1,1);
INSERT INTO message_templates (id,name,category,channel,subject,body,active,created_by) VALUES (2,'Screening invite','screening','email','Next step: screening call for {{job_title}}','Hi {{first_name}},

We would like to schedule a 30-minute screening call for {{job_title}}. Please share two or three times that work for you.

Best,
VSolutions Talent Team',1,1);
INSERT INTO message_templates (id,name,category,channel,subject,body,active,created_by) VALUES (3,'Interview invitation','interview_invite','email','Interview invitation — {{job_title}}','Hi {{first_name}},

You have been invited (or have accepted an invitation) to interview for {{job_title}}. Your interviewer panel details are on your candidate portal.

Best,
VSolutions Talent Team',1,1);
INSERT INTO message_templates (id,name,category,channel,subject,body,active,created_by) VALUES (4,'Reschedule confirmation','reschedule','email','Your interview has been rescheduled','Hi {{first_name}},

Your interview for {{job_title}} has been moved. The new time is confirmed in your candidate portal.

Best,
VSolutions Talent Team',1,1);
INSERT INTO message_templates (id,name,category,channel,subject,body,active,created_by) VALUES (5,'Not moving forward','rejection','email','Update on your application — {{job_title}}','Hi {{first_name}},

Thank you for your time. After careful review we will not be moving forward with your application for {{job_title}}.

We would welcome you applying for future roles.

Best,
VSolutions Talent Team',1,1);
INSERT INTO message_templates (id,name,category,channel,subject,body,active,created_by) VALUES (6,'Offer released','offer','email','Your offer for {{job_title}}','Hi {{first_name}},

We are delighted to share an offer for {{job_title}}. The full package and start date are available in the attachment.

Best,
VSolutions Talent Team',1,1);
INSERT INTO message_templates (id,name,category,channel,subject,body,active,created_by) VALUES (7,'Withdrawal acknowledgement','withdrawal','email','We received your withdrawal','Hi {{first_name}},

We have noted your withdrawal from {{job_title}}. Thank you for letting us know.

Best,
