INSERT INTO automation_rules (id,name,description,trigger_event,conditions,actions,enabled,test_mode,created_by) VALUES
    (1,'Acknowledge every new application','Sends the acknowledgement template when an application is created.','application.created','[{"field":"consent_status","op":"neq","value":"opt_out"}]','[{"type":"send_message","template_id":1}]',1,0,1),
    (2,'Create manager review task on shortlist','When an application moves to manager review, create a task for the hiring manager.','application.stage_changed','[{"field":"to_stage","op":"eq","value":"manager_review"}]','[{"type":"create_task","type_":"review","title":"Hiring manager review required","due_in_hours":48}]',1,0,1),
    (3,'Feedback reminder after interview','Creates a reminder task when an interview is completed.','interview.completed','[]','[{"type":"create_task","type_":"feedback","title":"Collect interview feedback","due_in_hours":24}]',1,0,1),
    (4,'Requisition aging alert','Notifies talent ops when an open requisition passes 45 days.','job.aged','[{"field":"days_open","op":"gt","value":45}]','[{"type":"notify_user","title":"Requisition past 45 days","user_id":1}]',1,0,1),
    (5,'Reject acknowledgement (test mode)','Would send a rejection note; kept in test mode for review.','application.rejected','[]','[{"type":"send_message","template_id":5}]',1,1,1),
    (6,'Interview invite on scheduling','Sends invitation details when an interview is scheduled.','interview.scheduled','[]','[{"type":"send_message","template_id":3}]',0,0,1);
